t\\t\\t            {{ batches.update({data.batch_no: data.qty}) or \\\"\\\" }}\\n\\t\\t\\t        {% endif %}\\n\\t\\t\\t    {% endfor %}\\n\\t\\t\\t{% endif %}\\n\\n\\t\\t\\t<td style=\\\"width: 3%;\\\">{{ row.idx }}</td>\\n\\t\\t\\t<td style=\\\"width: 20%;\\\">\\n\\t\\t\\t\\t{{ row.item_name }}\\n\\t\\t\\t\\t{% if row.item_code != row.item_name -%}\\n\\t\\t\\t\\t<br>Item Code: {{ row.item_code}}\\n\\t\\t\\t\\t{%- endif %}\\n\\t\\t\\t</td>\\n\\t\\t\\t<td style=\\\"width: 10%; text-align: right;\\\">{{ row.qty }} {{ row.uom or row.stock_uom }}</td>\\n\\t\\t\\t\\n\\t\\t\\t<td style=\\\"width: 30%; text-align: left;\\\">{{ serial_nos|join(\',\') }}</td>\\n\\t\\t\\t<td style=\\\"width: 30%;\\\">\\n\\t\\t\\t    {% if batches %}\\n                    {% for batch_no, qty in batches.items() %}\\n                        <p> {{batch_no}} : {{qty}} {{ row.uom or row.stock_uom }} </p>\\n                    {% endfor %}\\n                {% endif %}\\n\\t\\t\\t</td>\\n\\t\\t\\t\\n\\t\\t</tr>\\n\\t\\t{%- endfor -%}\\n\\t</tbody>\\n</table>\\n\"}]',1,0,NULL,NULL,NULL,NULL),
('Return POS Invoice','2025-07-09 16:24:08.634749','2020-05-14 17:13:29.354015','Administrator','Administrator',0,0,NULL,'POS Invoice',NULL,'Selling','en','Yes',1,0,NULL,'Jinja',0,'<style>\n	.print-format table, .print-format tr, \n	.print-format td, .print-format div, .print-format p {\n		font-family: Tahoma, sans-serif;\n		line-height: 150%;\n		vertical-align: middle;\n	}\n	@media screen {\n		.print-format {\n			width: 4in;\n			padding: 0.25in;\n			min-height: 8in;\n		}\n	}\n</style>\n\n{% if letter_head %}\n    {{ letter_head }}\n{% endif %}\n\n<p class=\"text-center\" style=\"margin-bottom: 1rem\">\n	{{ doc.company }}<br>\n	{{ doc.select_print_heading or _(\"Return Invoice\") }}<br>\n</p>\n<p>\n	<b>{{ _(\"Receipt No\") }}:</b> {{ doc.name }}<br>\n	<b>{{ _(\"Original Invoice\") }}:</b> {{ doc.return_against }}<br>\n	<b>{{ _(\"Date\") }}:</b> {{ doc.get_formatted(\"posting_date\") }}<br>\n	<b>{{ _(\"Customer\") }}:</b> {{ doc.customer_name }}\n</p>\n\n<hr>\n<table class=\"table table-condensed cart no-border\">\n	<thead>\n		<tr>\n			<th width=\"50%\">{{ _(\"Item\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ _(\"Qty\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ _(\"Amount\") }}</th>\n		</tr>\n	</thead>\n	<tbody>\n		{%- for item in doc.items -%}\n		<tr>\n			<td>\n				{{ item.item_code }}\n				{%- if item.item_name != item.item_code -%}\n					<br>{{ item.item_name }}\n				{%- endif -%}\n				{%- if item.serial_no -%}\n					<br><b>{{ _(\"SR.No\") }}:</b><br>\n					{{ item.serial_no | replace(\"\\n\", \", \") }}\n				{%- endif -%}\n			</td>\n			<td class=\"text-right\">{{ item.qty }}<br>@ {{ item.get_formatted(\"rate\") }}</td>\n			<td class=\"text-right\">{{ item.get_formatted(\"amount\") }}</td>\n		</tr>\n		{%- endfor -%}\n	</tbody>\n</table>\n<table class=\"table table-condensed no-border\">\n	<tbody>\n		<tr>\n			{% if doc.flags.show_inclusive_tax_in_print %}\n				<td class=\"text-right\" style=\"width: 70%\">\n					{{ _(\"Total Excl. Tax\") }}\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"net_total\", doc) }}\n				</td>\n			{% else %}\n				<td class=\"text-right\" style=\"width: 70%\">\n					{{ _(\"Total\") }}\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"total\", doc) }}\n				</td>\n			{% endif %}\n		</tr>\n		{%- for row in doc.taxes -%}\n		  {%- if not row.included_in_print_rate or doc.flags.show_inclusive_tax_in_print -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 70%\">\n				    {% if \'%\' in row.description %}\n					    {{ row.description }}\n					{% else %}\n					    {{ row.description }}@{{ row.rate }}%\n					{% endif %}\n				</td>\n				<td class=\"text-right\">\n					{{ row.get_formatted(\"tax_amount\", doc)}}\n				</td>\n			<tr>\n		  {%- endif -%}\n		{%- endfor -%}\n\n		{%- if doc.discount_amount -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				{{ _(\"Discount\") }}\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"discount_amount\") }}\n			</td>\n		</tr>\n		{%- endif -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Grand Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"grand_total\") }}\n			</td>\n		</tr>\n		{%- if doc.rounded_total -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Rounded Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"rounded_total\") }}\n			</td>\n		</tr>\n		{%- endif -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Paid Amount\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"paid_amount\") }}\n			</td>\n		</tr>\n		{%- if doc.change_amount -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 75%\">\n					<b>{{ _(\"Change Amount\") }}</b>\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"change_amount\")}}\n				</td>\n			</tr>\n		{%- endif -%}\n	</tbody>\n</table>\n<hr>\n<p>{{ doc.terms or \"\" }}</p>\n<p class=\"text-center\">{{ _(\"Thank you, please visit again.\") }}</p>',NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,'Default',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
